```sql
/* Подсчёт общего числа атомов в молекулах, содержащих тройные связи и атомы фосфора или брома */
SELECT COUNT(DISTINCT a."atom_id") AS total_atoms
FROM "atom" a
JOIN "molecule" m ON a."molecule_id" = m."molecule_id"
WHERE a."molecule_id" IN (
    /* Молекулы с тройной связью */
    SELECT b."molecule_id"
    FROM "bond" b
    WHERE b."bond_type" = '#'
)
AND a."molecule_id" IN (
    /* Молекулы, содержащие фосфор или бром */
    SELECT a2."molecule_id"
    FROM "atom" a2
    WHERE LOWER(a2."element") IN ('p', 'br')
);
```

```sql
/* Выбираем молекулы, у которых есть одинарные связи (bond_type = '-') */
/* и которые не являются канцерогенными (label = '-') */
/* Возвращаем топ-3 уникальных molecule_id в алфавитном порядке */
SELECT DISTINCT m."molecule_id"
FROM "molecule" m
JOIN "bond" b ON b."molecule_id" = m."molecule_id"
WHERE m."label" = '-'
  AND b."bond_type" = '-'
ORDER BY m."molecule_id"
LIMIT 3;
```

