```sql
/* Вычисляем процент молекул, содержащих водород (element = 'h'), среди канцерогенных молекул (label = '+') */
SELECT
    /* Доля молекул с водородом среди канцерогенных, умноженная на 100 */
    SUM(CASE WHEN LOWER(a."element") = 'h' THEN 1 ELSE 0 END) * 100.0
    / COUNT(DISTINCT m."molecule_id") AS percentage
FROM "molecule" m
/* Соединяем молекулы с атомами */
JOIN "atom" a
    ON a."molecule_id" = m."molecule_id"
/* Ограничиваем только канцерогенными молекулами */
WHERE m."label" = '+';
```

```sql
/* Вычисляем процент карциногенных молекул среди связей типа '#' (тройные связи) */
SELECT
    /* Процент = (число троиных связей у карциногенных молекул * 100) / общее число связей у карциногенных молекул */
    (SUM(CASE WHEN b."bond_type" = '#' THEN 1 ELSE 0 END) * 100.0) / COUNT(b."bond_id") AS percent
FROM "molecule" m
JOIN "bond" b ON b."molecule_id" = m."molecule_id"
WHERE m."label" = '+';
```

