```sql
/* Вычисляем процент пользователей с 0 upvotes среди комментариев со score от 5 до 10 */
SELECT
    /* Процент: количество пользователей с upvotes = 0 делим на общее количество, умножаем на 100 */
    (COUNT(DISTINCT CASE WHEN u."upvotes" = 0 THEN c."userid" END)::numeric
     / NULLIF(COUNT(DISTINCT c."userid"), 0)) * 100 AS percentage
FROM "comments" c
JOIN "users" u ON u."id" = c."userid"
WHERE c."score" BETWEEN 5 AND 10;
```

