```sql
/* Доля супергероев с alignment = 'Bad' от общего числа, и сколько из них издано Marvel Comics */
SELECT
    /* Процент "плохих" супергероев от общего количества */
    (COUNT(*) FILTER (WHERE al."alignment" = 'Bad')::numeric
        / NULLIF(COUNT(sh."id"), 0)) * 100 AS bad_percentage,
    /* Количество "плохих" супергероев, изданных Marvel Comics */
    COUNT(*) FILTER (WHERE al."alignment" = 'Bad' AND p."publisher_name" = 'Marvel Comics') AS bad_marvel_count
